const T = 'tenant-fid'

function base(
  id: string,
  name: string,
  description: string,
  ownerId: string,
  status: TenantPack['capabilities'][number]['status'] = 'active',
  tags: string[] = [],
) {
  return entityBase(T, id, name, description, ownerId, status, tags, ['fidelity-seed-v1'])
}

function cap(
  id: string,
  name: string,
  description: string,
  ownerId: string,
  level: 1 | 2,
  domain: string,
  opts: {
    parentId?: string
    maturityCurrent: number
    maturityTarget: number
    strategicImportance: number
    riskScore: number
    investmentPriority: number
    strategicObjectiveIds: string[]
    tags?: string[]
  },
) {
  return {
    ...base(id, name, description, ownerId, 'active', opts.tags ?? []),
    level,
    parentId: opts.parentId,
    domain,
    maturityCurrent: opts.maturityCurrent,
    maturityTarget: opts.maturityTarget,
    strategicImportance: opts.strategicImportance,
    riskScore: opts.riskScore,
    investmentPriority: opts.investmentPriority,
    strategicObjectiveIds: opts.strategicObjectiveIds,
  }
}

function app(
  id: string,
  name: string,
  description: string,
  ownerId: string,
  fields: {
    lifecycle: TenantPack['applications'][number]['lifecycle']
    businessValue: number
    technicalHealth: number
    criticality: TenantPack['applications'][number]['criticality']
    businessOwnerId: string
    technologyOwnerId: string
    annualCostBand: TenantPack['applications'][number]['annualCostBand']
    userReach: number
    dataSensitivity: TenantPack['applications'][number]['dataSensitivity']
    deploymentModel: TenantPack['applications'][number]['deploymentModel']
    vendorProduct: string
    strategicAlignment: number
    supportedCapabilityIds: string[]
    endOfSupportDate?: string
    duplicationClusterId?: string
    tags?: string[]
  },
) {
  return {
    ...base(id, name, description, ownerId, 'active', fields.tags ?? []),
    lifecycle: fields.lifecycle,
    businessValue: fields.businessValue,
    technicalHealth: fields.technicalHealth,
    criticality: fields.criticality,
    businessOwnerId: fields.businessOwnerId,
    technologyOwnerId: fields.technologyOwnerId,
    annualCostBand: fields.annualCostBand,
    userReach: fields.userReach,
    dataSensitivity: fields.dataSensitivity,
    deploymentModel: fields.deploymentModel,
    vendorProduct: fields.vendorProduct,
    strategicAlignment: fields.strategicAlignment,
    supportedCapabilityIds: fields.supportedCapabilityIds,
    endOfSupportDate: fields.endOfSupportDate,
    duplicationClusterId: fields.duplicationClusterId,
  }
}

